test('Forfettario audit 360: HTTP 429 rispetta Retry-After senza retry aggressivo',async t=>{
  const server=await startServer();let browser;t.after(async()=>{if(browser)await browser.close();await server.close();});browser=await chromium.launch({headless:true});
  const context=await browser.newContext(),page=await context.newPage();await page.goto(`${server.baseUrl}/__forfettario-race`);const clientSource=await readFile(path.join(ROOT,'tools','forfettario','authoritative-client.js'),'utf8');
  await page.evaluate(()=>{let calls=0;globalThis.__rateCalls=()=>calls;globalThis.TAL_API={invalidate(){},async request(){calls+=1;return new Response('{}',{status:429,headers:{'content-type':'application/json','retry-after':'2'}});}};});await page.addScriptTag({content:clientSource});
  const limited=await page.evaluate(async()=>{const payload={marker:'rate-limited'};await globalThis.ForfettarioAuthoritative.schedule(payload);const snapshot=globalThis.ForfettarioAuthoritative.snapshot(payload),callsBeforeWait=globalThis.__rateCalls();await new Promise(resolve=>setTimeout(resolve,150));const callsBeforeRetryAfter=globalThis.__rateCalls();await new Promise(resolve=>setTimeout(resolve,2100));const callsAfterRetry=globalThis.__rateCalls();await new Promise(resolve=>setTimeout(resolve,150));const callsFinal=globalThis.__rateCalls();globalThis.ForfettarioAuthoritative.invalidate();return {snapshot,callsBeforeWait,callsBeforeRetryAfter,callsAfterRetry,callsFinal};});
  assert.equal(limited.snapshot.status,'error');assert.equal(limited.snapshot.diagnostics[0].code,'SERVICE_RATE_LIMITED');assert.equal(limited.snapshot.diagnostics[0].details.retryAfterMs,2000);assert.match(limited.snapshot.diagnostics[0].message,/Troppe richieste ravvicinate/);assert.equal(limited.callsBeforeWait,1);assert.equal(limited.callsBeforeRetryAfter,1,'nessun retry prima di Retry-After');assert.equal(limited.callsAfterRetry,2,'un solo retry dopo Retry-After');assert.equal(limited.callsFinal,2,'nessuna catena di retry aggressiva');await context.close();
});

